    var markerSuffix = null;

    function getAlignmentSize(wp, targetPanel) {
        var data = wp && wp.data ? wp.data : null;
        var fixedW = data ? Number(data.worldpanel_fixed_width) : 0;
        var fixedH = data ? Number(data.worldpanel_fixed_height) : 0;
        if (fixedW > 0 && fixedH > 0) {
            return {
                w: fixedW,
                h: fixedH,
                mode: "fixed",
            };
        }

        var useDesiredSize = !!(data && data.worldpanel_size_mode === "desired");
        var panelW = useDesiredSize ? (targetPanel.desiredlayoutwidth || targetPanel.actuallayoutwidth || 0) : (targetPanel.actuallayoutwidth || 0);
        var panelH = useDesiredSize ? (targetPanel.desiredlayoutheight || targetPanel.actuallayoutheight || 0) : (targetPanel.actuallayoutheight || 0);
        return {
            w: panelW,
            h: panelH,
            mode: useDesiredSize ? "desired" : "actual",
        };
    }

    function isDebugEnabled() {
        var cfg = GameUI && GameUI.CustomUIConfig ? GameUI.CustomUIConfig() : null;
        return !!(cfg && cfg.boss_health_debug);
    }

    function logLayout(reason) {
        if (!isDebugEnabled()) return;
        var rootW = rootPanel ? rootPanel.actuallayoutwidth : (panel ? panel.actuallayoutwidth : -1);
        var host = panel ? panel.GetParent() : null;
        var hostW = host ? host.actuallayoutwidth : -1;
        var hostH = host ? host.actuallayoutheight : -1;
        var hostX = host ? host.actualxoffset : -1;
        var hostY = host ? host.actualyoffset : -1;
        var frame = panel.FindChildTraverse("BossHealthFrame");
        var content = panel.FindChildTraverse("BossHealthContent");
        var frameW = frame ? frame.actuallayoutwidth : -1;
        var contentW = content ? content.actuallayoutwidth : -1;
        var segW = segmentsContainer ? segmentsContainer.actuallayoutwidth : -1;
        var mulW = multiplierContainer ? multiplierContainer.actuallayoutwidth : -1;
        var segX = segmentsContainer ? segmentsContainer.actualxoffset : -1;
        var mulX = multiplierContainer ? multiplierContainer.actualxoffset : -1;
        var wp = panel ? panel.WorldPanel : null;
        var hAlign = wp && wp.hAlign !== undefined ? wp.hAlign : "nil";
        var vAlign = wp && wp.vAlign !== undefined ? wp.vAlign : "nil";
        var rootCenter = rootW >= 0 ? (rootW * 0.5) : -1;
        var segCenter = (segX >= 0 && segW >= 0) ? (segX + segW * 0.5) : -1;
        var centerDelta = (rootCenter >= 0 && segCenter >= 0) ? (segCenter - rootCenter) : -9999;
        $.Msg("[BossHealthUI]", reason,
            "ent=", entityIndex,
            "hostW=", hostW,
            "hostH=", hostH,
            "hostX=", hostX,
            "hostY=", hostY,
            "rootW=", rootW,
            "frameW=", frameW,
            "contentW=", contentW,
            "segW=", segW,
            "segX=", segX,
            "mulW=", mulW,
            "mulX=", mulX,
            "mulText=", (multiplierLabel && multiplierLabel.text) ? multiplierLabel.text : "",
            "hA=", hAlign,
            "vA=", vAlign,
            "rootC=", rootCenter,
            "segC=", segCenter,
            "dC=", centerDelta);
    }

    function ensureDebugMarkers() {
        if (!isDebugEnabled()) return;
        var layer = panel ? panel.GetParent() : null;
        if (!layer) return;
        if (!entityIndex || entityIndex <= 0) return;
        if (!markerSuffix) {
            markerSuffix = String(entityIndex);
        }
        if (!worldAnchorMarker) {
            var oldWorld = layer.FindChildTraverse("WorldAnchorMarker_" + markerSuffix);
            if (oldWorld) oldWorld.DeleteAsync(0);
