            var centerParent = framePanel || panel;
            var oldCenter = centerParent.FindChildTraverse("PanelCenterMarker_" + markerSuffix);
            if (oldCenter) oldCenter.DeleteAsync(0);
            panelCenterMarker = $.CreatePanel("Panel", centerParent, "PanelCenterMarker_" + markerSuffix);
            panelCenterMarker.style.width = "10px";
            panelCenterMarker.style.height = "10px";
            panelCenterMarker.style.backgroundColor = "#2aff5e";
            panelCenterMarker.style.border = "1px solid #000000";
            panelCenterMarker.style.borderRadius = "50%";
            panelCenterMarker.style.zIndex = "9999";
            panelCenterMarker.style.horizontalAlign = "center";
